#!/bin/zsh
# usage: dump_store.sh <session> <hash> <out.bin>   (read-only; never creates the database)
playwright-cli -s=$1 --raw eval "(async function(){ var dbs = indexedDB.databases ? await indexedDB.databases() : []; if (!dbs.some(function(d){ return d.name === '/idbfs'; })) return 'none'; return await new Promise(function(resolve){ setTimeout(function(){ resolve('timeout'); }, 10000); var req=indexedDB.open('/idbfs'); req.onerror=function(){ resolve('err'); }; req.onsuccess=function(){ var db=req.result; if (!db.objectStoreNames.contains('FILE_DATA')) { db.close(); return resolve('none'); } var g=db.transaction('FILE_DATA','readonly').objectStore('FILE_DATA').get('/idbfs/$2/PlayerPrefs'); g.onsuccess=function(){ db.close(); if(!g.result) return resolve('none'); var u8=g.result.contents; var s=''; for(var i=0;i<u8.length;i++) s+=String.fromCharCode(u8[i]); resolve(btoa(s)); }; g.onerror=function(){ db.close(); resolve('err'); }; }; }); })()" 2>/dev/null | tail -1 | tr -d '"' > $3.b64
python3 "$(dirname $0)/parse_store.py" $3.b64 $3
